body { font-family: system-ui; padding: 30px; }
input { display: none; }
label { cursor: pointer; display: inline-flex; align-items: center; gap: 8px; }
label::before { content: ""; width: 18px; height: 18px; border: 2px solid #94a3b8; border-radius: 4px; display: inline-block; }
input:checked + label::before { content: "\2713"; color: #fff; background: #16a34a; border-color: #16a34a; text-align: center; line-height: 18px; font-size: 13px; }

